import{_ as t,o as a,c as o,a0 as i}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"🚀 System Deployment & Hosting Guide","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/deployment.md","filePath":"deployment/deployment.md"}'),s={name:"deployment/deployment.md"};function d(n,e,r,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="🚀-system-deployment-hosting-guide" tabindex="-1">🚀 System Deployment &amp; Hosting Guide <a class="header-anchor" href="#🚀-system-deployment-hosting-guide" aria-label="Permalink to &quot;🚀 System Deployment &amp; Hosting Guide&quot;">​</a></h1><p>WealthFam is a sophisticated, containerized microservice ecosystem. To maintain the highest standards of data integrity and privacy (the <strong>Sovereign Circle</strong> model), we have refined our deployment pathways.</p><hr><h2 id="🏛️-deployment-strategy" tabindex="-1">🏛️ Deployment Strategy <a class="header-anchor" href="#🏛️-deployment-strategy" aria-label="Permalink to &quot;🏛️ Deployment Strategy&quot;">​</a></h2><p>WealthFam is built for <strong>privacy-first local hosting</strong>. We provide an official demo for exploration, but for personal use, local orchestration is the mandatory path until our SaaS offering is launched.</p><h3 id="_1-🌐-official-live-demo" tabindex="-1">1. 🌐 Official Live Demo <a class="header-anchor" href="#_1-🌐-official-live-demo" aria-label="Permalink to &quot;1. 🌐 Official Live Demo&quot;">​</a></h3><p>The only authorized cloud instance of WealthFam is hosted on Render. This instance is for evaluation purposes.</p><ul><li><strong>Demo Instance:</strong> <a href="https://wealthfam.onrender.com" target="_blank" rel="noreferrer">https://wealthfam.onrender.com</a></li><li><strong>Deployment Status:</strong> 🟢 Operational (Render Free Tier)</li><li><strong>Test Credentials:</strong><ul><li>Username: <code>demo@demo.com</code></li><li>Password: <code>demo123</code></li></ul></li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>The demo database is ephemeral and resets periodically. Do not input real sensitive financial data into the demo instance.</p></div><h3 id="_2-🐳-self-hosting-docker-monolith-—-local-lan-or-public-internet" tabindex="-1">2. 🐳 Self-Hosting (Docker Monolith — Local LAN or Public Internet) <a class="header-anchor" href="#_2-🐳-self-hosting-docker-monolith-—-local-lan-or-public-internet" aria-label="Permalink to &quot;2. 🐳 Self-Hosting (Docker Monolith — Local LAN or Public Internet)&quot;">​</a></h3><p>For your personal data, we support self-hosting via Docker. This ensures your data stays on hardware you control.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Pull the official orchestration stack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/WealthFam/Infra.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Infra/docker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Configure required secrets (.env)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate 32-byte random hex secrets (\`openssl rand -hex 32\`) for:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># SECRET_KEY, BLIND_INDEX_SALT, ADMIN_SECRET_KEY, ADMIN_PASSWORD, POSTGRES_PASSWORD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3a. Launch on a local LAN IP (e.g. http://192.168.0.7):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3b. Launch on the Public Internet with automatic Let&#39;s Encrypt HTTPS + HSTS:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOMAIN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">app.yourdomain.com</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.tls.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Fail-Closed Secrets &amp; Loopback-Only Admin Console</strong>:</p><ul><li>Docker Compose and the Backend/Admin-Backend services refuse to start in <code>ENVIRONMENT=production</code> if required secrets are missing or weak.</li><li><code>Admin-Web</code> is bound strictly to <code>127.0.0.1:8080</code>. Access it securely from another machine via SSH tunnel (<code>ssh -L 8080:127.0.0.1:8080 user@server</code>) or VPN/Tailnet.</li><li>When upgrading an existing database with legacy plaintext rows or Vault files, run the idempotent backfill once: <code>docker exec -it wealthfam python /app/scripts/encrypt_legacy_data.py</code></li></ul></div><p><strong>Hardware Recommendation:</strong></p><ul><li><strong>Entry</strong>: Raspberry Pi 4 (4GB+)</li><li><strong>Optimal</strong>: Dedicated NAS or Home Server (8GB+ RAM, SSD)</li></ul><hr><h2 id="📅-roadmap-managed-hosting-saas" tabindex="-1">📅 Roadmap: Managed Hosting (SaaS) <a class="header-anchor" href="#📅-roadmap-managed-hosting-saas" aria-label="Permalink to &quot;📅 Roadmap: Managed Hosting (SaaS)&quot;">​</a></h2><p>We recognize that not every user wants to maintain their own hardware. We are in the final stages of architecting the <strong>WealthFam Cloud (SaaS)</strong>.</p><ul><li><strong>Status</strong>: 🛠️ In Development (Alpha)</li><li><strong>Features</strong>: <ul><li>Automated Backups</li><li>Managed Security Updates</li><li>100% Privacy via Encrypted Storage Volumes (PostgreSQL/DuckDB)</li><li>Multi-tenant isolation</li></ul></li></ul><hr><h2 id="⚙️-core-configuration" tabindex="-1">⚙️ Core Configuration <a class="header-anchor" href="#⚙️-core-configuration" aria-label="Permalink to &quot;⚙️ Core Configuration&quot;">​</a></h2><p>Whether running locally or in development, the environment is controlled via these primary variables:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ENVIRONMENT</code></td><td><code>production</code> (Docker) / <code>development</code> (local)</td><td>Deployment mode (<code>development</code>, <code>staging</code>, <code>production</code>)</td></tr><tr><td><code>POSTGRES_USER</code> / <code>POSTGRES_PASSWORD</code> / <code>POSTGRES_DB</code></td><td><code>wealthfam</code> / <strong>Required</strong> / <code>wealthfam</code></td><td>PostgreSQL credentials (internal-only; port <code>5432</code> is never exposed on host)</td></tr><tr><td><code>SECRET_KEY</code></td><td><strong>Required (32+ chars)</strong></td><td>Core JWT signing &amp; key-derivation secret</td></tr><tr><td><code>BLIND_INDEX_SALT</code></td><td><strong>Required (32+ chars)</strong></td><td>Dedicated HMAC-SHA256 salt for encrypted PII blind indexes (separate from <code>SECRET_KEY</code>)</td></tr><tr><td><code>PREVIOUS_SECRET_KEYS</code></td><td>(empty)</td><td>Comma-separated rotated keys for seamless legacy <code>MultiFernet</code> decryption</td></tr><tr><td><code>TENANT_SEAL_STRICT</code></td><td><code>true</code> (prod) / <code>false</code> (dev)</td><td>Enforces strict per-user KEK/DEK unsealing in RAM</td></tr><tr><td><code>ALLOW_PUBLIC_REGISTRATION</code></td><td><code>false</code> (prod) / <code>true</code> (dev)</td><td>Gates <code>/api/v1/auth/register</code> after family accounts are created</td></tr><tr><td><code>ENABLE_API_DOCS</code></td><td><code>false</code> (prod) / <code>true</code> (dev)</td><td>Controls Swagger UI (<code>/docs</code>), ReDoc (<code>/redoc</code>), and OpenAPI schema across <code>Backend</code>, <code>Admin-Backend</code>, and <code>Parser</code></td></tr><tr><td><code>RATE_LIMIT_ENABLED</code></td><td><code>true</code> (prod) / <code>false</code> (dev)</td><td>Sliding-window per-IP rate limiting on auth &amp; telemetry endpoints</td></tr><tr><td><code>ADMIN_USERNAME</code> / <code>ADMIN_PASSWORD</code></td><td><code>admin</code> / <strong>Required</strong></td><td>Initial bootstrap credentials for <code>Admin-Web</code> (<code>127.0.0.1:8080</code>)</td></tr><tr><td><code>ADMIN_SECRET_KEY</code></td><td><strong>Required (32+ chars)</strong></td><td>Independent JWT signing secret for Admin Console</td></tr><tr><td><code>DOMAIN</code></td><td>(required for TLS overlay)</td><td>Public domain for automatic Let&#39;s Encrypt HTTPS via <code>docker-compose.tls.yml</code></td></tr><tr><td><code>ALLOWED_ORIGINS</code></td><td><code>http://localhost</code></td><td>Explicit comma-separated CORS allowed origins</td></tr><tr><td><code>PARSER_SERVICE_URL</code></td><td><code>http://parser:8001/v1</code></td><td>Stateless financial SMS, email, statement &amp; CAS parser microservice</td></tr><tr><td><code>TELEMETRY_DATABASE_URL</code></td><td><code>duckdb:////data/telemetry.duckdb</code></td><td>Admin telemetry timeseries, scrubbed logs &amp; parser templates</td></tr><tr><td><code>LOGOS_STORAGE_PATH</code></td><td><code>/data/logos</code></td><td>Individual brand logo image files managed by Admin Console</td></tr><tr><td><code>VAULT_STORAGE_PATH</code></td><td><code>/data/vault</code></td><td>Encrypted Document Vault &amp; thumbnails (<code>VaultFileCipher</code> v2, <code>0700</code> permissions)</td></tr><tr><td><code>GEMINI_API_KEY</code></td><td>-</td><td>AI-powered transaction Precision analysis</td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>INFO</code></td><td>System observability depth</td></tr></tbody></table><hr><h2 id="📱-mobile-connectivity" tabindex="-1">📱 Mobile Connectivity <a class="header-anchor" href="#📱-mobile-connectivity" aria-label="Permalink to &quot;📱 Mobile Connectivity&quot;">​</a></h2><p>To connect your mobile device to your instance:</p><ol><li><strong>Release APK (Recommended)</strong>: Enforces <strong>HTTPS-only</strong> (<code>usesCleartextTraffic=&quot;false&quot;</code>). Connect to your public domain (<code>https://app.yourdomain.com</code>), a Cloudflare Tunnel, or Tailscale HTTPS (<code>https://pi.&lt;tailnet&gt;.ts.net</code>).</li><li><strong>Debug APK (Local Dev Only)</strong>: Permits cleartext HTTP on local LAN/emulator IPs (<code>http://10.0.2.2:8000</code> or <code>http://192.168.x.x:80</code>) via <code>android/app/src/debug/res/xml/network_security_config.xml</code>.</li><li>Open <strong>WealthFam Mobile</strong> → <strong>Settings</strong>, set your Backend URL, and log in.</li></ol><hr><h2 id="🆘-technical-support" tabindex="-1">🆘 Technical Support <a class="header-anchor" href="#🆘-technical-support" aria-label="Permalink to &quot;🆘 Technical Support&quot;">​</a></h2><p>If you encounter orchestration issues:</p><ul><li><strong><a href="https://wealthfam.github.io/docs" target="_blank" rel="noreferrer">Documentation Hub</a></strong></li><li><strong><a href="https://github.com/WealthFam/Infra" target="_blank" rel="noreferrer">GitHub Infrastructure Repository</a></strong></li><li><strong>Discord Community</strong>: <a href="https://discord.gg/wealthfam" target="_blank" rel="noreferrer">Join the Precision Lab</a></li></ul><hr><div align="center"> *Built for Privacy · Powered by AI · Managed by You* *Made with ❤️ by WGLabz* </div>`,33)])])}const g=t(s,[["render",d]]);export{m as __pageData,g as default};
